import { cn } from '../../utils/cn';

interface SpriteImgProps {
  src: string;
  width: number;
  height?: number;
  alt: string;
  className?: string;
}

/** Pixel-perfect <img> for data-URL sprites generated by the SpriteManager. */
export function SpriteImg({ src, width, height, alt, className }: SpriteImgProps) {
  return <img src={src} alt={alt} width={width} height={height} draggable={false} className={cn('pixelated', className)} style={{ width, height: height ?? 'auto' }} />;
}
